<script setup lang="ts">
import {ref} from 'vue'
import ReferenceIcon from '@/ui/ReferenceIcon.vue'
import type {FunctionDraft} from './rule-builder-draft'
import {propertyOperationLabel,propertyOperationGlyph,type PropertyOperationDraft} from './property-operations-draft'
const props=defineProps<{modelValue:readonly (FunctionDraft|PropertyOperationDraft)[];disabled?:boolean;hideAdd?:boolean;sorting?:boolean;detail?:boolean;recoveryPending?:boolean;recovering?:boolean}>()
const emit=defineEmits<{add:[];edit:[id:string];remove:[id:string];move:[id:string,direction:-1|1];reorder:[from:string,to:string];sort:[value:boolean];cancelSort:[];recover:[];format:[id:string,format:string]}>()
const dragged=ref('')
function start(event:DragEvent,id:string){if(props.disabled||!props.sorting){event.preventDefault();return}dragged.value=id;event.dataTransfer?.setData('text/plain',id)}
function drop(id:string){const from=dragged.value;dragged.value='';if(!props.disabled&&props.sorting&&from&&from!==id)emit('reorder',from,id)}
</script>
<template><section class="preprocess-operation-table">
 <template v-if="detail"><header class="detail-operation-header"><h3>操作</h3><div><el-button v-if="recoveryPending" link type="primary" :disabled="recovering" @click="emit('recover')">读取核对</el-button><el-button v-if="sorting" link type="primary" :disabled="disabled" @click="emit('cancelSort')">取消</el-button><el-button v-if="sorting" link type="primary" :disabled="disabled" @click="emit('sort',false)">保存排序</el-button><el-button v-else link type="primary" :disabled="disabled" @click="emit('sort',true)">排序</el-button><el-button v-if="!hideAdd" link type="primary" :disabled="disabled||sorting||modelValue.length>=32" @click="emit('add')">添加操作</el-button></div></header>
 <div class="detail-operation-list"><div v-for="(row,index) in modelValue" :key="row.id" class="detail-operation-row" :data-function-id="row.id" :draggable="!!sorting&&!disabled" @dragstart="start($event,row.id)" @dragend="dragged=''" @dragover.prevent @drop.prevent="drop(row.id)"><span class="detail-operation-icon"><ReferenceIcon :glyph="propertyOperationGlyph(row)"/></span><span class="detail-operation-name">{{propertyOperationLabel(row)}}<small v-if="'kind' in row">({{row.id}})</small></span><div class="detail-row-actions"><el-button v-if="sorting" size="small" :disabled="disabled" :aria-label="'拖动排序操作 '+(index+1)" @keydown.up.prevent="emit('move',row.id,-1)" @keydown.down.prevent="emit('move',row.id,1)"><ReferenceIcon glyph="󰍜"/></el-button><el-button size="small" :disabled="disabled||sorting" :aria-label="'编辑操作 '+(index+1)" @click="emit('edit',row.id)"><ReferenceIcon glyph="󰏫"/></el-button><el-button size="small" type="danger" :disabled="disabled||sorting" :aria-label="'移除操作 '+(index+1)" @click="emit('remove',row.id)"><ReferenceIcon glyph="󰆴"/></el-button></div></div></div></template>
 <template v-else><el-table :data="[...modelValue]" :show-header="false" empty-text="暂无数据" row-key="id">
  <el-table-column><template #default="{row,$index}"><div class="operation-name" :data-function-id="row.id" :draggable="!!sorting&&!disabled" @dragstart="start($event,row.id)" @dragend="dragged=''" @dragover.prevent @drop.prevent="drop(row.id)"><ReferenceIcon v-if="sorting" glyph="󰍜"/><span>{{propertyOperationLabel(row)}}</span><span class="sort-controls" v-if="sorting"><el-button text :disabled="disabled||$index===0" :aria-label="'上移操作 '+($index+1)" @click="emit('move',row.id,-1)">上移</el-button><el-button text :disabled="disabled||$index===modelValue.length-1" :aria-label="'下移操作 '+($index+1)" @click="emit('move',row.id,1)">下移</el-button></span></div></template></el-table-column>
  <el-table-column width="180"><template #default="{row,$index}"><el-select v-if="'format' in row" :model-value="row.format" :disabled="disabled||sorting" :aria-label="'操作 '+($index+1)+' 函数格式'" @update:model-value="emit('format',row.id,$event)"><el-option label="CommonJS" value="COMMON_JS"/><el-option label="函数表达式" value="FUNCTION_EXPRESSION"/></el-select></template></el-table-column>
  <el-table-column width="50"><template #default="{row,$index}"><el-button circle size="small" :disabled="disabled||sorting" :aria-label="'编辑操作 '+($index+1)" @click="emit('edit',row.id)"><ReferenceIcon glyph="󰏫"/></el-button></template></el-table-column>
  <el-table-column width="50"><template #default="{row,$index}"><el-button circle size="small" type="danger" :disabled="disabled||sorting" :aria-label="'移除操作 '+($index+1)" @click="emit('remove',row.id)"><ReferenceIcon glyph="󰆴"/></el-button></template></el-table-column>
 </el-table>
 <div class="table-actions"><el-button v-if="!hideAdd" :disabled="disabled||sorting||modelValue.length>=32" @click="emit('add')">添加操作</el-button><el-button v-if="modelValue.length>1" :disabled="disabled" @click="emit('sort',!sorting)">{{sorting?'完成排序':'排序'}}</el-button></div>
</template></section></template>
<style scoped>
.preprocess-operation-table{min-width:0}.preprocess-operation-table :deep(.el-table__cell){padding:12px 0}.preprocess-operation-table :deep(.cell){padding:0 10px}.preprocess-operation-table :deep(.el-button.is-circle){width:28px;height:28px;padding:7px}.operation-name{display:flex;align-items:center;gap:10px;min-height:28px;font-size:14px;color:#606266}.operation-name[draggable=true]{cursor:grab}.sort-controls{display:flex;gap:8px;margin-left:auto}.sort-controls .el-button+.el-button{margin-left:0}.table-actions{display:flex;gap:10px;margin-top:18px}.table-actions>.el-button+.el-button{margin-left:0}.detail-operation-header{display:flex;justify-content:space-between;align-items:center;padding:16px 20px;border-bottom:1px solid #ebeef5}.detail-operation-header h3{font-size:14px;line-height:20px;font-weight:500;color:#303133;margin:0}.detail-operation-header>div{display:flex;gap:14px}.detail-operation-header .el-button+.el-button{margin-left:0}.detail-operation-row{display:flex;align-items:center;gap:20px;min-height:86px;padding:20px 28px;border-bottom:1px solid #ebeef5;font-size:14px;color:#606266}.detail-operation-row:last-child{border-bottom:0}.detail-operation-row[draggable=true]{cursor:grab}.detail-operation-icon{display:inline-flex;justify-content:center;align-items:center;background:#16834d;color:#fff;width:30px;height:30px;border-radius:3px;font-size:17px;flex:none}.detail-operation-name small{font-size:12px;margin-left:7px;color:#909399}.detail-row-actions{display:flex;gap:7px;align-items:center;margin-left:auto}.detail-row-actions .el-button+.el-button{margin-left:0}
</style>
